def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)

    # Handle the case where one of the coefficients is zero
    if a == 0:
        if n % b != 0:
            return None
        return (0, n // b)

    if b == 0:
        if n % a != 0:
            return None
        return (n // a, 0)

    # Use extended Euclidean algorithm to find gcd and coefficients
    def extended_gcd(x, y):
        if x == 0:
            return y, 0, 1
        gcd, x1, y1 = extended_gcd(y % x, x)
        x2 = y1 - (y // x) * x1
        y2 = x1
        return gcd, x2, y2

    gcd, x0, y0 = extended_gcd(a, b)

    # If n is not divisible by gcd, no solution exists
    if n % gcd != 0:
        return None

    # Scale the solution to match n
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    return (x, y)
```

