def k_smallest_pairs(arr1, arr2, k):
    import heapq

    # Generate all possible pairs and use a min heap to get k smallest
    pairs = []
    for a in arr1:
        for b in arr2:
            pairs.append((a + b, a, b))

    # Sort by sum and take first k
    pairs.sort(key=lambda x: x[0])

    result = []
    for i in range(k):
