def is_undulating(n):
    s = str(n)
    if len(s) < 2:
        return False

    # Check if the number alternates between two digits
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False

    # Check if the pattern alternates between two digits
    first_digit = s[0]
    second_digit = s[1]

    for i in range(2, len(s)):
        if s[i] != first_digit and s[i] != second_digit:
            return False

    # Ensure the pattern is consistent (alternating)
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            return False

    return True
```

