def is_Diff(n):
    # A number is divisible by 11 if the alternating sum of its digits is divisible by 11
    digits = [int(d) for d in str(n)]
    alternating_sum = 0
    for i in range(len(digits)):
        if i % 2 == 0:
            alternating_sum += digits[i]
        else:
            alternating_sum -= digits[i]
    return alternating_sum % 11 == 0
```

